document.addEventListener('DOMContentLoaded', function() {
    const calculateOhmButton = document.getElementById('calculate-ohm');
    const ohmResult = document.getElementById('ohm-result');

    calculateOhmButton.addEventListener('click', function() {
        const current = parseFloat(document.getElementById('current').value);
        const voltage = parseFloat(document.getElementById('voltage').value);
        const resistance = parseFloat(document.getElementById('resistance').value);

        if (isNaN(current) || isNaN(voltage) || isNaN(resistance)) {
            ohmResult.textContent = "Por favor, insira valores numéricos válidos.";
            return;
        }

        const unknown = (voltage / current);
        const calculatedResistance = (unknown * current);

        ohmResult.textContent = "R = " + calculatedResistance.toFixed(2); // Exibe com 2 casas decimais
    });
});
